# === Config ===
DATA_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "data")

def restore_vm():
    # Use VBoxManage commands to perform the restore operation
    try:
        os.popen("vboxmanage controlvm ubuntu poweroff").read()
        os.popen('VBoxmanage list runningvms').read()
        os.popen("VBoxManage snapshot ubuntu restore restore").read()
        os.popen("vboxmanage startvm --type headless ubuntu").read()

    except subprocess.CalledProcessError as e:
        print(f"Error: {e.output}")

def load_large_json(file_path):
    data = {}
    with open(file_path, "r") as json_file:
        for line in json_file:
            item = json.loads(line)
            data.update(item)
    return data

def save_large_json(data, file_path):
    with open(file_path, "w") as json_file:
        for key, value in data.items():
            json.dump({key: value}, json_file)
            json_file.write('\n')
session_dict=load_large_json(os.path.join(DATA_DIR, "5-session去重.json"))
