    already_read = list(session_chat_dict.keys())

    print(len(already_read) + 1)
    print(len(session_dict))
    i=1
    for session_id in session_dict:
        print(i)
        i += 1
        if session_id in already_read :
            continue


        # Extract the list of commands to execute
        session_comd=session_dict[session_id]


        # SSH connection info
        hostname = '169.254.140.133'
        port = 40000
        username = 'root'
        password = os.environ["HONEYPOT_SSH_PASSWORD"]  # was hardcoded in the original script

        # Initialize the SSH client
        ssh_client = paramiko.SSHClient()
        ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())

        try:
            # Connect to the SSH server
            ssh_client.connect(hostname, port, username, password)

            # Create an interactive shell channel
            ssh_shell = ssh_client.invoke_shell()
            ssh_shell.settimeout(60)
            command_output = b''
            while True:
                while not ssh_shell.recv_ready():
                    pass
                command_output += ssh_shell.recv(65535)
                if command_output[-2:] == b'# ':
                    break
            command_chats = []
            # Send commands to the shell channel
            for cmd in session_comd:
                # Array storing one set of conversational command requests and echoes
                if cmd =="END":
                    break

                cmd = cmd[5:]
                # Replace download-resource commands
                if cmd in url_replace_dict:
                    cmd = url_replace_dict[cmd]
                #print(cmd)

                start_time = time.time()
                timeout = 6 # timeout in seconds

                command_output = b''
                # Time-bound execution of statements that otherwise need interaction to stop
                if cmd in ["debug shell", "top","cat /bin/ls|more",
                           'scp -t /tmp/2p8unLIG',"scp -t /tmp/Lhtln3CT","scp -t /tmp/tZft1Zbk","scp -t /tmp/tseLLRfT","scp -t /tmp/5RcJ2tf9","scp -t /tmp/PHri0doL","scp -t /tmp/ePxJOVoq" ]:
                    ssh_shell.send('timeout 2 '+cmd + '\n')
                else:
                    ssh_shell.send(cmd +'\n' )
                while True:
                    # # Wait for the command to finish executing
                    # while not ssh_shell.recv_ready():
                    #     pass
                    # Read the echoed lines and append them to the output
                    if cmd in ["passwd"]:
                        time.sleep(6)
                    command_output += ssh_shell.recv(65535)

                    # Check whether a command-completion marker appeared (e.g. the shell prompt)
                    if command_output[-2:] == b'# ' or command_output[-2:] == b'> ' or "#!/usr/bin/sh" in cmd :
                        command_output = command_output.decode('utf-8', errors='ignore')

                        break

                    if time.time() - start_time > timeout:


                        command_output = command_output.decode('utf-8', errors='ignore')
                        ssh_shell.close()
                        ssh_shell = ssh_client.invoke_shell()
                        ssh_shell.settimeout(10)
                        command_output1 = b''
                        while True:
                            while not ssh_shell.recv_ready():
                                pass
                            command_output1 += ssh_shell.recv(65535)
                            if command_output1[-2:] == b'# ':
                                break
                        break

                # Store the command echo
                command_chats.append((cmd,command_output))


            session_chat_dict[session_id] = command_chats
            print(session_id,command_chats)

        except paramiko.AuthenticationException:
            restore_vm()
            time.sleep(10)
            break
            #print(f"Authentication failed: session_id:\n {session_id} ")
        except paramiko.SSHException as e:

            print(f"SSH error: session_id:\n {session_id}  \n{str(e)}")
            restore_vm()
            time.sleep(10)
